/* 知夏 · 挂机结算脚本
 *
 * 妹妹自己在这里活着。玩家关掉页面多久，她的状态就按真实时间掉多少。
 * 这份脚本负责：进场算一次、玩家每次开口之前再算一次，把账记在同一份变量里。
 *
 * 变量放在哪：楼层变量的 `stat_data` 里，和面板读写的**是同一份**。
 * 面板改的那些也会被 MVU 带到下一楼，所以两边不会各记一套。
 * 记账用的 `$记账.上次时刻` 是真实毫秒时间戳，一起存在那里。
 *
 * 起点怎么定：取「变量表里记的上次时刻」和「localStorage 里记的脚本启动时刻」里更早的那个。
 * 前者覆盖跨聊天的离开，后者覆盖同一个页面一直开着、中途没发过消息的情况。
 *
 * 算术全在 `离线结算.ts` 里，是纯函数，本地能直接跑数字核对（`验收/离线结算表.mjs`）。
 */

import { 算离线, 应用到妹妹, 说时长, 最长补偿小时, type 差额, type 收支 } from '../离线结算';

const 记账键 = 'zhixia:上次启动';

/** 距上次算账不足这个时间就不算，免得来回切页也刷一堆提示。 */
const 最小结算间隔分钟 = 10;

type 记账 = {
  上次时刻: number;
  上次结算: string;
  已结算次数: number;
};

function 取楼层选项() {
  return { type: 'message' as const, message_id: -1 };
}

function 读变量表(): Record<string, any> | null {
  try {
    const 表 = getVariables(取楼层选项()) as Record<string, any>;
    const 数据 = 表?.stat_data;
    return 数据 && typeof 数据 === 'object' ? 数据 : null;
  } catch (错误) {
    console.warn('[挂机] 读变量失败', 错误);
    return null;
  }
}

function 取记账(数据: Record<string, any>): 记账 {
  const 原 = 数据?.$记账 ?? {};
  return {
    上次时刻: Number(原.上次时刻 ?? 0) || 0,
    上次结算: String(原.上次结算 ?? ''),
    已结算次数: Number(原.已结算次数 ?? 0) || 0,
  };
}

function 记启动时刻() {
  try {
    localStorage.setItem(记账键, String(Date.now()));
  } catch {
    // 存不了就算了，变量表里的时间戳还能兜底
  }
}

function 取启动时刻(): number {
  try {
    return Number(localStorage.getItem(记账键) ?? 0) || 0;
  } catch {
    return 0;
  }
}

/** 取两个时间戳里更早的那个当起点。0 表示没有，直接忽略。 */
function 取起点(表里: number, 内存里: number) {
  const 候选 = [表里, 内存里].filter(值 => Number.isFinite(值) && 值 > 0);
  return 候选.length ? Math.min(...候选) : 0;
}

let 上一份差额: 差额 | null = null;
let 上一句回执 = '';

/**
 * 算一次账。
 * 第一次进场（没有任何时间戳）时只记时刻、不扣东西，否则新聊天的第一眼就会看到妹妹变惨。
 * `安静` 为真时不打日志，用于后台静默结算。
 */
function 结算一次(安静 = false) {
  const 数据 = 读变量表();
  if (!数据) return null;

  const 现在 = Date.now();
  const 记账 = 取记账(数据);
  const 起点 = 取起点(记账.上次时刻, 取启动时刻());

  if (起点 <= 0) {
    数据.$记账 = { 上次时刻: 现在, 上次结算: '第一次见面，先记下此刻。', 已结算次数: 记账.已结算次数 };
    写回(数据);
    记启动时刻();
    return null;
  }

  const 差额 = 算离线({
    上次时刻: 起点,
    现在时刻: 现在,
    现在的饥饿: Number(数据.妹妹?.饥饿 ?? 70),
    现在的心情: Number(数据.妹妹?.心情 ?? 60),
    现在的健康: Number(数据.妹妹?.健康 ?? 90),
    现在的钱: Number(数据.钱 ?? 0),
    病症: String(数据.妹妹?.病症 ?? '无'),
  });

  上一份差额 = 差额;

  if (差额.离开小时 * 60 < 最小结算间隔分钟) {
    // 没走多久，不扣，但把时刻推上去
    数据.$记账 = { ...记账, 上次时刻: 现在 };
    写回(数据);
    记启动时刻();
    return null;
  }

  const 应用 = 应用到妹妹(数据, 差额);
  const 回执 = 写回执(差额, 数据, 应用);
  数据.$记账 = { 上次时刻: 现在, 上次结算: 回执, 已结算次数: 记账.已结算次数 + 1 };
  写回(数据);
  记启动时刻();
  上一句回执 = 回执;

  if (!安静) console.info('[挂机] 结算完成：' + 回执);
  return { 差额, 应用, 回执 };
}

/** 生成一句给玩家看的回执。面板上的按钮与提示都用这一句。 */
function 写回执(差额: 差额, 数据: Record<string, any>, 应用: 收支) {
  const 段 = ['你走了 ' + 说时长(差额.离开小时) + '。'];
  if (差额.被截断) 段.push('超过 ' + 最长补偿小时 + ' 小时的部分不再算。');
  if (差额.饥饿) 段.push('她饿了 ' + Math.abs(差额.饥饿) + ' 点');
  if (差额.心情) 段.push('心情掉了 ' + Math.abs(差额.心情) + ' 点');
  if (差额.健康) 段.push('身体也跟着垮 ' + Math.abs(差额.健康) + ' 点');
  if (差额.钱) 段.push('这几天他在外面干活，净剩 ' + 差额.钱 + ' 元');
  if (应用.年龄长了一岁) 段.push('这段时间她过了一个生日，' + 数据.妹妹.年龄 + ' 岁了');
  if (差额.饥饿 === 0 && 差额.心情 === 0 && 差额.健康 === 0 && !应用.年龄长了一岁) 段.push('她没什么变化');
  return 段.join('');
}

/** 把整份数据写回去。失败时把这次的事说清楚，不要静默丢掉。 */
function 写回(数据: Record<string, any>) {
  try {
    updateVariablesWith(表 => {
      表.stat_data = 数据;
      return 表;
    }, 取楼层选项());
    return true;
  } catch (错误) {
    console.warn('[挂机] 写回变量失败，这一次结算没有落盘', 错误);
    return false;
  }
}

$(function () {
  console.info('[挂机] 挂上了');

  // 进场先算一次。这时脚本刚启动，localStorage 里的时间就是上次会话结束的时刻。
  结算一次();

  // 玩家每次开口之前，把这段停留也算进去。
  eventOn(tavern_events.MESSAGE_SENT, () => 结算一次(true));

  // 换聊天之后重新记一次时刻，避免带着上一个局面的账。
  eventOn(tavern_events.CHAT_CHANGED, () => {
    记启动时刻();
    结算一次();
  });

  // 页面一直开着的时候也要自己走。否则搁在那儿一小时，数值一直不动，
  // 看起来就像「她没在过日子」。十分钟问一次，间隔不够的会被跳过，不会乱扣。
  const 心跳 = window.setInterval(() => 结算一次(true), 10 * 60 * 1000);

  $(window).on('pagehide', () => {
    window.clearInterval(心跳);
    // 关页面 = 这次会话结束，把时刻记在 localStorage 里，下次进场从这里接着算。
    记启动时刻();
  });
});
